import 'package:cloud_firestore/cloud_firestore.dart';
import 'model_utils.dart';
class AssessmentResultModel { const AssessmentResultModel({required this.id,required this.studentId,required this.assessmentId,required this.totalScore,required this.categoryScores,required this.completedAt}); final String id,studentId,assessmentId; final double totalScore; final Map<String,num> categoryScores; final DateTime completedAt; factory AssessmentResultModel.fromFirestore(DocumentSnapshot<Map<String,Object?>> d)=>AssessmentResultModel(id:d.id,studentId:d['studentId'] as String,assessmentId:d['assessmentId'] as String,totalScore:(d['totalScore'] as num).toDouble(),categoryScores:numbersFrom(d['categoryScores']),completedAt:dateFromValue(d['completedAt'])!); Map<String,Object?> toFirestore()=>{'studentId':studentId,'assessmentId':assessmentId,'totalScore':totalScore,'categoryScores':categoryScores,'completedAt':Timestamp.fromDate(completedAt)}; }
